import{_ as n,o as r,c as t,ag as e}from"./chunks/framework.PVHj0As1.js";const s="/pub-blog/assets/image-20260304223649081.Cyct7sV4.png",a="/pub-blog/assets/image-20260304223812477.Bp0tSvau.png",p="/pub-blog/assets/workflow.CDHw0uRy.png",d="/pub-blog/assets/image-20260304225318261.zoW2KED_.png",g="/pub-blog/assets/security-sandbox.CRnezh_P.png",l="/pub-blog/assets/image-20260304230202746.BKe232dP.png",k="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",A=JSON.parse('{"title":"阿里重磅推出 QoderWork，普通人都能提效的智能工作站","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/阿里重磅推出QoderWork普通人都能提效的智能工作站/阿里重磅推出QoderWork普通人都能提效的智能工作站.md","filePath":"AI人工智能/阿里重磅推出QoderWork普通人都能提效的智能工作站/阿里重磅推出QoderWork普通人都能提效的智能工作站.md","lastUpdated":1772636630000,"__rawMarkdown":"# 阿里重磅推出 QoderWork，普通人都能提效的智能工作站\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n\\n![](assets/image-20260304223649081.png)\\n\\n你是否还在为日常繁琐的办公事务头疼？处理 **Excel** 数据要折腾半天公式，整理 **PDF** 报告要来回复制粘贴，写一份周报还得切换好\\n\\n几个工具……现在，这一切可能只需要你**说一句话**就搞定了。\\n\\n最近，一款名为 **QoderWork** 的桌面级 AI 智能体助手正式上线，它把 AI 的能力从**聊天问答**拉到了**真正替你干活**的新阶段。今天我们\\n\\n就来聊聊，这款产品到底有什么不一样。\\n\\n---\\n\\n## 从写代码到做日常——AI 能力的一次跨界\\n\\n**QoderWork** 脱胎于 **Qoder** 智能体编程平台。此前，**Qoder** 已经在开发者圈子里积累了大量口碑，其 AI Agent 能力在代码生成、调\\n\\n试和工程管理方面表现亮眼。而 **QoderWork** 做的事情，是把这套成熟的 Agent 能力**从代码领域扩展到了每个人的日常工作场景**。\\n\\n\\n\\n简单来说：你不需要会写代码，也不需要懂任何技术，只要能描述清楚你的需求，**QoderWork** 就能自动规划任务、执行操作、\\n\\n直接交付结果。\\n\\n![](assets/image-20260304223812477.png)\\n\\n---\\n\\n## 说需求，交结果——不止是聊天\\n\\n市面上的 AI 工具大多还停留在\\"你问我答\\"的阶段。但 QoderWork 的定位完全不同，官方用了一句非常直接的话来概括：**\\"不止聊天，搞定一切。\\"**\\n\\n当你告诉 QoderWork\\"帮我把这份销售数据做成柱状图，导出为 PDF\\"，它不会只给你一段操作指南，而是直接打开你的文件、分析数据、生成图表、导出文件——全程自主完成，你只需要验收结果。\\n\\n\\n\\n这背后是 QoderWork 的**自主工作流规划能力**：它会根据你的需求自动拆解任务步骤，逐步执行，遇到问题还能自行调整方案。用官方的话说，这是一个\\"本地运行、自主规划、安全可控的 AI 工作搭子\\"。\\n\\n![](assets/workflow.png)\\n\\n---\\n\\n## 能力可扩展，场景无边界\\n\\n一个好用的工具，光靠开箱即用还不够，还得能长出新能力。QoderWork 在这一点上做了两件关键的事：\\n\\n\\n\\n**第一，内置多种主流 MCP（Model Context Protocol）。** 这意味着它可以直接对接各类数据源和服务，开箱就能处理 Excel、PDF、\\n\\nWord、PPT 等常见办公格式，不需要你把文件上传到云端，本地就能搞定。\\n\\n\\n\\n**第二，支持自定义 Skills。** 如果你有特定的工作流程或独特的业务需求，可以为 QoderWork 扩展专属技能，让它越用越懂你、越用\\n\\n越顺手。\\n\\n![](assets/image-20260304225318261.png)\\n\\n\\n\\n无论你是做数据分析、内容创作、项目管理，还是日常行政事务，QoderWork 都能覆盖到。\\n\\n\\n\\n---\\n\\n## 数据安全，始终在你手里\\n\\n在 AI 工具越来越强大的今天，数据安全是很多人最关心的问题。\\n\\nQoderWork 在这方面的策略非常清晰：**所有操作都在本地沙盒中运**\\n\\n\\n\\n**行，数据始终留在你的设备上。**\\n\\n\\n\\n未经你的授权，QoderWork 不会访问任何内容。\\n\\n\\n\\n你可以精确控制它能看到哪些文件夹、能执行哪些操作。\\n\\n用官方的承诺来说——\\"你始终掌控一切。\\"\\n\\n\\n\\n这种设计对于处理公司敏感文件、客户数据的职场人来说，无疑吃了一颗定心丸。\\n\\n![](assets/security-sandbox.png)\\n\\n---\\n\\n## 谁适合用 QoderWork？\\n\\n坦白讲，QoderWork 的目标用户不是程序员（他们有 Qoder IDE），\\n\\n而是**每一个日常需要和电脑打交道的普通人**。\\n\\n如果你经常需要处理各种格式的文档，或者希望把重复性的办公事务自动化，\\n\\n又或者只是想让 AI 真正帮你\\"干活\\"而不只是\\"聊天\\"，\\n\\n那 QoderWork 值得一试。目前它支持 **macOS 14 以上**和 **Windows 10 以上**系统，\\n\\n可以直接到官网下载体验。\\n\\n![](assets/image-20260304230202746.png)\\n\\n---\\n\\n## 写在最后\\n\\n从 ChatGPT 掀起 AI 浪潮到现在，我们见证了太多\\"能聊\\"的 AI，但真正能\\"动手干活\\"的 AI 工作站才刚刚起步。QoderWork 的出现，\\n\\n代表了一种新的方向：**AI 不再只是顾问，而是真正的同事。**\\n\\n如果你对 QoderWork 感兴趣，可以访问官网了解更多：https://qoder.com/qoderwork\\n\\n---\\n\\n> 你觉得 AI 智能体助手会改变我们的工作方式吗？欢迎在评论区留言讨论。\\n\\n## 最后 [](#最后)\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),i={name:"AI人工智能/阿里重磅推出QoderWork普通人都能提效的智能工作站/阿里重磅推出QoderWork普通人都能提效的智能工作站.md"};function c(h,o,_,u,Q,W){return r(),t("div",null,[...o[0]||(o[0]=[e("",58)])])}const q=n(i,[["render",c]]);export{A as __pageData,q as default};
